import type { ConsoleLevel, ConsoleMessage } from './Console.types';
import { CONSOLE_CLASSES } from './Console.constants';

// ─── Creación de mensajes ──────────────────────────────────────────────────────

export function generateId(): string {
    return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export function createMessage(
    content: unknown,
    level: ConsoleLevel = 'info',
    label?: string,
): ConsoleMessage {
    return {
        id: generateId(),
        timestamp: new Date().toISOString(),
        content,
        level,
        label,
    };
}

// ─── Formateo ──────────────────────────────────────────────────────────────────

export function formatTimestamp(isoString: string): string {
    return new Date(isoString).toLocaleTimeString(undefined, {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
    });
}

export function isJsonable(value: unknown): boolean {
    return typeof value === 'object' && value !== null;
}

export function formatContentAsString(content: unknown): string {
    if (content === null) return 'null';
    if (content === undefined) return 'undefined';
    if (typeof content === 'string') return content;
    if (typeof content === 'number' || typeof content === 'boolean') return String(content);
    return JSON.stringify(content, null, 2);
}

// ─── Clases CSS ────────────────────────────────────────────────────────────────

export function buildConsoleClasses(theme: string, unstyled?: boolean, className?: string): string {
    const base = CONSOLE_CLASSES.root;
    if (unstyled) return [base, `${base}--unstyled`, className].filter(Boolean).join(' ');
    return [
        base,
        theme === 'dark' ? CONSOLE_CLASSES.themeDark : CONSOLE_CLASSES.themeLight,
        className,
    ]
        .filter(Boolean)
        .join(' ');
}

export function buildMessageClasses(level: ConsoleLevel): string {
    const levelMap: Record<ConsoleLevel, string> = {
        info: CONSOLE_CLASSES.messageInfo,
        warn: CONSOLE_CLASSES.messageWarn,
        error: CONSOLE_CLASSES.messageError,
        success: CONSOLE_CLASSES.messageSuccess,
        debug: CONSOLE_CLASSES.messageDebug,
    };
    return [CONSOLE_CLASSES.message, levelMap[level]].filter(Boolean).join(' ');
}

export function buildFilterBtnClasses(
    level: string,
    activeLevel: string,
): string {
    const levelMap: Record<string, string> = {
        info: CONSOLE_CLASSES.filterInfo,
        warn: CONSOLE_CLASSES.filterWarn,
        error: CONSOLE_CLASSES.filterError,
        success: CONSOLE_CLASSES.filterSuccess,
        debug: CONSOLE_CLASSES.filterDebug,
    };
    return [
        CONSOLE_CLASSES.filterBtn,
        levelMap[level] ?? '',
        level === activeLevel ? CONSOLE_CLASSES.filterBtnActive : '',
    ]
        .filter(Boolean)
        .join(' ');
}

// ─── Filtrado ──────────────────────────────────────────────────────────────────

export function filterMessages(
    messages: ConsoleMessage[],
    levelFilter: string,
    searchQuery: string,
): ConsoleMessage[] {
    return messages.filter((msg) => {
        if (levelFilter !== 'all' && msg.level !== levelFilter) return false;
        if (searchQuery) {
            const text = formatContentAsString(msg.content).toLowerCase();
            const label = (msg.label ?? '').toLowerCase();
            const q = searchQuery.toLowerCase();
            if (!text.includes(q) && !label.includes(q)) return false;
        }
        return true;
    });
}

// ─── Exportar ─────────────────────────────────────────────────────────────────

export function exportMessagesAsLog(messages: ConsoleMessage[]): void {
    const text = messages
        .map(
            (m) =>
                `[${formatTimestamp(m.timestamp)}] [${m.level.toUpperCase()}]${m.label ? ` (${m.label})` : ''} ${formatContentAsString(m.content)}`,
        )
        .join('\n');
    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `console-${Date.now()}.log`;
    a.click();
    URL.revokeObjectURL(url);
}
